	AuthorCounts   map[common.Address]int `json:"author"`         // Block proposal counts
	BlockRange     BlockRange             `json:"blockRange"`     // Block range information
	RoundStats     RoundStats             `json:"roundStats"`     // Round distribution statistics
}

